const payload = $input.first().json;
if (payload.errors?.length) throw new Error('Shopify order query failed: ' + payload.errors.map((error) => error.message).join('; '));
const orders = payload.data?.orders?.nodes || [];
const quote = (value) => value == null ? 'null' : "'" + String(value).replace(/'/g, "''") + "'";
const statements = orders.map((order) => {
  const money = order.totalPriceSet?.shopMoney || {};
  return `select public.wa_marketing_attribute_order(${quote(order.customer?.id)}, ${quote(order.id)}, ${quote(order.name)}, ${quote(order.createdAt)}::timestamptz, ${Number(money.amount || 0)}, ${quote(money.currencyCode || '')}, ${quote(order.landingPageDisplayText)});`;
});
statements.push("insert into public.wa_marketing_settings (key, value, updated_at) values ('order_attribution_connected', 'true'::jsonb, now()) on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;");
statements.push(`select ${orders.length}::integer as orders_checked, count(*) filter (where attributed_order_id is not null)::integer as orders_attributed from public.wa_marketing_recipients;`);
return [{ json: { sql: statements.join(' ') } }];
